 app.patch('/api/v1/admin/content/:id',{preHandler:allow(permissions.content),schema:{...adminSchema('updateContent','CMS'),params,body:contentInput.extend({revision:z.number().int().positive()}),response:{200:C.content,...errors}}},async req=>{const b=req.body;const old=required((await db.query('SELECT state FROM content WHERE id=$1',[req.params.id])).rows[0]);if((b.state==='published'||old.state==='published'||b.publishAt)&&!permitted(req.actor!.role,permissions.publish))throw new HttpError(403,'PUBLISH','Publisher role required for published content');if(b.state==='published'||b.publishAt)await ensurePublication(b.kind==='page'&&['impressum','privacy'].includes(b.slug));return normalize<z.infer<typeof C.content>>(await updateEditorialContent(req.params.id,b,req.actor!,req.id));});
